#include <stdio.h>
#include <stdlib.h>

int main(void) {
    size_t n = 5;
    int *a = malloc(n * sizeof(int));
    if (!a) { fprintf(stderr, "malloc failed\n"); return 1; }

    for (size_t i = 0; i < n; i++) a[i] = (int)(i * 10);
    for (size_t i = 0; i < n; i++) printf("%d%c", a[i], i + 1 == n ? '\n' : ' ');

    free(a);
    a = NULL;                 /* 释放后置空 */
    return 0;
}
